# VitalRecord: dataclass + validator
from dataclasses import dataclass, field
from typing import Any

@dataclass
class Vitalrecord:
    record_id: str = None  # ID
    kind: str = None  # birth/death/marriage
    date: str = None  # ISO 8601
    jurisdiction: str = None  # County/state
    registered_at: str = None  # Filed

REQUIRED = ["record_id", "kind", "date", "jurisdiction"]

def validate(rec: dict) -> list:
    errors = []
    for f in REQUIRED:
        if f not in rec or rec[f] is None:
            errors.append(f'missing: {f}')
    return errors

sample = {'record_id': 'VR-2026-88120', 'kind': 'birth', 'date': '2026-05-30', 'jurisdiction': 'Cook County, IL', 'registered_at': '2026-06-02'}
print('validation errors:', validate(sample))
print('record ok:', not validate(sample))

